<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/config.php';
require_once dirname(__DIR__, 2) . '/database/config/db.php';
require_once dirname(__DIR__, 2) . '/security/middleware/AuthMiddleware.php';
AuthMiddleware::startSession();
$user=AuthMiddleware::requireAuth();
$csrf=AuthMiddleware::csrfToken();
$role=strtolower((string)($user['role']??'student'));
$dashboard=match($role){'admin','super_admin','moderator'=>BASE_URL.'/modules/admin/dashboard.php','facilitator'=>BASE_URL.'/modules/facilitator/dashboard.php',default=>BASE_URL.'/modules/student/dashboard.php'};
$name=(string)($user['full_name']??$user['username']??'User');$username=(string)($user['username']??'');$email=(string)($user['email']??'');$bio=(string)($user['bio']??'');$initial=strtoupper(substr($name!==''?$name:$username,0,1));$gradient=(string)($user['avatar_color_gradient']??'#a855f7,#ec4899');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ecollab — Settings</title><meta name="csrf-token" content="<?=htmlspecialchars($csrf,ENT_QUOTES)?>"><style>
:root{--bg:#090d15;--nav:#0d121c;--card:#121927;--input:#192235;--line:#273248;--text:#f2f5fa;--muted:#8b98ad;--accent:#a855f7;--accent2:#ec4899}*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--text)}body{min-height:100vh}.shell{display:flex;min-height:100vh}.nav{width:255px;flex:0 0 255px;background:var(--nav);border-right:1px solid var(--line);padding:22px 14px;position:sticky;top:0;height:100vh}.brand{font-weight:850;font-size:17px;padding:4px 10px 25px;display:flex;align-items:center;gap:10px}.logo{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(135deg,var(--accent),var(--accent2));font-weight:900}.group{font-size:10px;font-weight:800;color:#62718a;letter-spacing:.09em;margin:16px 10px 7px;text-transform:uppercase}.navbtn{border:0;background:transparent;color:#aab5c7;width:100%;text-align:left;padding:10px;border-radius:8px;font:600 13px inherit;cursor:pointer}.navbtn:hover{background:#171e2b;color:#fff}.navbtn.active{background:#291842;color:#d8b4fe}.navbtn.logout{color:#f87171}.divider{height:1px;background:var(--line);margin:15px 10px}.main{flex:1;min-width:0;overflow:auto}.inner{max-width:980px;margin:auto;padding:38px 32px 70px}.title{font-size:27px;font-weight:850;margin-bottom:25px}.section{display:none}.section.active{display:block}.section h2{font-size:21px;margin:0 0 6px}.desc{color:var(--muted);font-size:13px;line-height:1.55;margin:0 0 20px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden;margin-bottom:18px}.head{font-size:14px;font-weight:800;padding:17px 20px;border-bottom:1px solid var(--line)}.body{padding:20px}.hero{display:flex;gap:16px;align-items:center;padding:20px;border:1px solid var(--line);border-radius:12px;margin-bottom:18px;background:linear-gradient(135deg,#19152a,#171523)}.avatar{width:68px;height:68px;border-radius:50%;display:grid;place-items:center;font-size:26px;font-weight:900;background:linear-gradient(135deg,<?=$gradient?>)}.heroname{font-weight:850;font-size:19px}.handle{font-size:12px;color:var(--muted);margin-top:3px}.badge{display:inline-block;margin-top:7px;padding:4px 8px;border-radius:99px;background:#2b1a43;color:#d8b4fe;font-size:10px;font-weight:800;text-transform:uppercase}.grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.field{display:flex;flex-direction:column;gap:7px}.full{grid-column:1/-1}.field label{font-size:10px;color:#8e9bb0;font-weight:850;letter-spacing:.07em;text-transform:uppercase}.field input,.field textarea,.field select{width:100%;background:var(--input);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:11px 12px;font:13px inherit;outline:none}.field textarea{min-height:105px;resize:vertical}.field input:focus,.field textarea:focus,.field select:focus{border-color:var(--accent);box-shadow:0 0 0 3px #a855f71a}.field input:disabled{opacity:.55}.hint{font-size:11px;color:#69778e}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}.btn{border:0;border-radius:8px;padding:10px 15px;font:800 12px inherit;cursor:pointer}.primary{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff}.secondary{background:#202a3d;color:#b8c1d1;border:1px solid #334058}.status{font-size:12px;margin-top:10px;min-height:16px}.ok{color:#4ade80}.err{color:#f87171}.row{display:flex;align-items:center;gap:16px;padding:17px 20px;border-bottom:1px solid var(--line)}.row:last-child{border-bottom:0}.copy{flex:1}.rname{font-size:13px;font-weight:800}.help{font-size:11px;color:var(--muted);line-height:1.45;margin-top:4px}.switch{width:43px;height:24px;border-radius:99px;background:#293448;border:1px solid #3b4960;position:relative;cursor:pointer;flex:0 0 auto}.switch:after{content:"";position:absolute;width:16px;height:16px;left:3px;top:3px;border-radius:50%;background:#8793a8;transition:.15s}.switch.on{background:linear-gradient(135deg,var(--accent),var(--accent2));border:0}.switch.on:after{left:24px;background:#fff}.choice{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.choice button{padding:15px;text-align:left;border:1px solid var(--line);border-radius:10px;background:#151d2c;color:var(--text);cursor:pointer}.choice button.active{border-color:var(--accent);background:#26183b}.choice b{display:block;font-size:12px}.choice span{font-size:10px;color:var(--muted)}.range{display:flex;align-items:center;gap:12px}.range input{flex:1;accent-color:var(--accent)}.range output{width:42px;text-align:right;color:#aeb9cb;font-size:11px}.modal{position:fixed;inset:0;background:#0009;display:none;place-items:center;padding:20px;z-index:5}.modal.open{display:grid}.modalbox{width:min(430px,100%);background:#121927;border:1px solid var(--line);border-radius:13px;box-shadow:0 20px 70px #0008;padding:22px}.modalbox h3{margin:0 0 6px}.modalbox p{color:var(--muted);font-size:12px}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}html[data-theme="light"]{--bg:#eef1f6;--nav:#fff;--card:#fff;--input:#f7f8fb;--line:#d7dce5;--text:#172033;--muted:#5d6a7f}html.high-contrast{--line:#64748b;--muted:#cbd5e1}html.no-motion *,html.no-motion *:before,html.no-motion *:after{transition:none!important;animation:none!important}@media(max-width:760px){.shell{display:block}.nav{width:100%;height:auto;position:relative;padding:10px}.group,.divider{display:none}.navbtn{display:none}.navbtn.active{display:block}.inner{padding:24px 14px 50px}.grid{grid-template-columns:1fr}.full{grid-column:auto}.choice{grid-template-columns:1fr}}
</style></head><body><div class="shell"><aside class="nav"><div class="brand"><span class="logo">E</span>Ecollab</div><div class="group">User Settings</div><button class="navbtn active" data-section="account">👤 My Account</button><button class="navbtn" data-section="profile">✨ Profiles</button><button class="navbtn" data-section="privacy">🔒 Privacy & Safety</button><button class="navbtn" data-section="connections">🤝 Connections</button><div class="group">App Settings</div><button class="navbtn" data-section="appearance">🎨 Appearance</button><button class="navbtn" data-section="notifications">🔔 Notifications</button><button class="navbtn" data-section="voice">🎙️ Voice & Audio</button><button class="navbtn" data-section="accessibility">♿ Accessibility</button><div class="divider"></div><button class="navbtn" onclick="location.href='<?=htmlspecialchars($dashboard,ENT_QUOTES)?>'">🏠 Dashboard</button><button class="navbtn" onclick="location.href='<?=BASE_URL?>/modules/chat/chat.php'">💬 Back to Chat</button><button class="navbtn logout" onclick="location.href='<?=BASE_URL?>/modules/auth/logout.php'">↪ Log Out</button></aside><main class="main"><div class="inner"><div class="title" id="title">My Account</div>
<section class="section active" id="section-account"><div class="hero"><div class="avatar" id="avatar"><?=htmlspecialchars($initial)?></div><div><div class="heroname" id="heroName"><?=htmlspecialchars($name)?></div><div class="handle">@<?=htmlspecialchars($username)?></div><span class="badge"><?=htmlspecialchars($role)?></span></div></div><div class="card"><div class="head">Account Information</div><div class="body"><form id="accountForm"><div class="grid"><div class="field"><label>Display Name</label><input id="displayName" maxlength="80" value="<?=htmlspecialchars($name)?>" required><span class="hint">Shown on your profile, chats and servers.</span></div><div class="field"><label>Username</label><input value="<?=htmlspecialchars($username)?>" disabled></div><div class="field full"><label>Email</label><input value="<?=htmlspecialchars($email)?>" disabled></div><div class="field full"><label>Bio</label><textarea id="bio" maxlength="500"><?=htmlspecialchars($bio)?></textarea></div></div><div class="actions"><button class="btn secondary" type="button" id="resetAccount">Reset</button><button class="btn primary">Save Changes</button></div><div class="status" id="accountStatus"></div></form></div></div><div class="card"><div class="head">Security</div><div class="row"><div class="copy"><div class="rname">Password</div><div class="help">Change your password after verifying the current one.</div></div><button class="btn secondary" id="openPassword">Change Password</button></div></div></section>
<section class="section" id="section-profile"><h2>Profiles</h2><p class="desc">These controls affect what other Ecollab members see when they open your profile.</p><div class="card"><div class="head">Profile Appearance</div><div class="body"><div class="grid"><div class="field"><label>Avatar Gradient</label><select id="gradient"><option value="#a855f7,#ec4899">Purple / Pink</option><option value="#3b82f6,#a855f7">Blue / Purple</option><option value="#06b6d4,#3b82f6">Cyan / Blue</option><option value="#10b981,#06b6d4">Green / Cyan</option><option value="#f97316,#ec4899">Orange / Pink</option></select></div><div class="field"><label>Profile Visibility</label><select id="visibility"><option value="everyone">Everyone in Ecollab</option><option value="servers">People who share a server with me</option><option value="connections">Connections only</option></select></div></div><div class="actions"><button class="btn primary" id="saveProfile">Save Profile Settings</button></div><div class="status" id="profileStatus"></div></div></div></section>
<section class="section" id="section-privacy"><h2>Privacy & Safety</h2><p class="desc">These preferences are saved to your account and used by Ecollab communication features.</p><div class="card"><div class="row"><div class="copy"><div class="rname">Allow Connection Requests</div><div class="help">Allow other members to connect with you directly.</div></div><div class="switch" data-key="connection_requests"></div></div><div class="row"><div class="copy"><div class="rname">Allow Direct Messages</div><div class="help">Allow non-connected members to start a direct conversation.</div></div><div class="switch" data-key="direct_messages"></div></div><div class="row"><div class="copy"><div class="rname">Show Activity Status</div><div class="help">Show whether you are online or active.</div></div><div class="switch" data-key="activity_status"></div></div><div class="row"><div class="copy"><div class="rname">Read Receipts</div><div class="help">Let conversation participants know when a message has been read.</div></div><div class="switch" data-key="read_receipts"></div></div><div class="row"><div class="copy"><div class="rname">Secret-chat Screenshot Alerts</div><div class="help">Keep screenshot alerts enabled for supported secret conversations.</div></div><div class="switch" data-key="screenshot_alerts"></div></div></div></section>
<section class="section" id="section-connections"><h2>Connections</h2><p class="desc">Control how Ecollab connects you with other students and facilitators.</p><div class="card"><div class="row"><div class="copy"><div class="rname">AI Suggested Matches</div><div class="help">Allow matching to use your collaboration preferences when suggesting study partners.</div></div><div class="switch" data-key="ai_matching"></div></div><div class="row"><div class="copy"><div class="rname">Existing Connections</div><div class="help">Your direct connections remain available in Chat and are not removed by changing matching preferences.</div></div><button class="btn secondary" onclick="location.href='<?=BASE_URL?>/modules/chat/chat.php'">Open Chat</button></div></div></section>
<section class="section" id="section-appearance"><h2>Appearance</h2><p class="desc">Theme and display preferences are applied immediately and saved to your account.</p><div class="card"><div class="head">Theme</div><div class="body"><div class="choice"><button data-theme="dark"><b>Dark</b><span>Default Ecollab interface.</span></button><button data-theme="light"><b>Light</b><span>Light interface.</span></button><button data-theme="system"><b>System</b><span>Follow your device preference.</span></button></div></div></div><div class="card"><div class="row"><div class="copy"><div class="rname">Compact Mode</div><div class="help">Reduce spacing in supported views.</div></div><div class="switch" data-key="compact_mode"></div></div><div class="row"><div class="copy"><div class="rname">Reduce Motion</div><div class="help">Reduce interface animations.</div></div><div class="switch" data-key="reduce_motion"></div></div></div></section>
<section class="section" id="section-notifications"><h2>Notifications</h2><p class="desc">Notification preferences are persisted on your account. Browser notifications also require browser permission.</p><div class="card"><div class="row"><div class="copy"><div class="rname">Desktop Notifications</div><div class="help">Allow Ecollab to request browser notification permission.</div></div><div class="switch" data-key="notification_desktop"></div></div><div class="row"><div class="copy"><div class="rname">New Messages</div><div class="help">Notify about new direct and channel messages.</div></div><div class="switch" data-key="notification_messages"></div></div><div class="row"><div class="copy"><div class="rname">Mentions</div><div class="help">Notify when another member mentions you.</div></div><div class="switch" data-key="notification_mentions"></div></div><div class="row"><div class="copy"><div class="rname">Match Suggestions</div><div class="help">Notify when new study-partner matches are available.</div></div><div class="switch" data-key="notification_matches"></div></div><div class="row"><div class="copy"><div class="rname">Notification Sound</div><div class="help">Enable notification audio where supported.</div></div><div class="switch" data-key="notification_sound"></div></div></div></section>
<section class="section" id="section-voice"><h2>Voice & Audio</h2><p class="desc">These settings are used when Ecollab creates microphone/audio streams in supported voice features.</p><div class="card"><div class="body"><div class="grid"><div class="field"><label>Input Device</label><select id="inputDevice"><option value="">Default microphone</option></select></div><div class="field"><label>Output Device</label><select id="outputDevice"><option value="">Default speaker</option></select></div><div class="field"><label>Microphone Volume</label><div class="range"><input id="micVolume" type="range" min="0" max="100"><output id="micOut">100%</output></div></div><div class="field"><label>Output Volume</label><div class="range"><input id="outVolume" type="range" min="0" max="100"><output id="outOut">100%</output></div></div></div></div><div class="row"><div class="copy"><div class="rname">Noise Suppression</div><div class="help">Request noise suppression for microphone streams.</div></div><div class="switch" data-key="noise_suppression"></div></div><div class="row"><div class="copy"><div class="rname">Echo Cancellation</div><div class="help">Request echo cancellation for microphone streams.</div></div><div class="switch" data-key="echo_cancellation"></div></div><div class="row"><div class="copy"><div class="rname">Automatic Gain Control</div><div class="help">Let the browser normalize microphone gain.</div></div><div class="switch" data-key="auto_gain_control"></div></div><div class="body"><button class="btn secondary" id="testMic">Test Microphone</button><span class="status" id="voiceStatus" style="display:inline-block;margin-left:10px"></span></div></div></section>
<section class="section" id="section-accessibility"><h2>Accessibility</h2><p class="desc">Accessibility preferences are applied immediately to this interface and stored on your account.</p><div class="card"><div class="row"><div class="copy"><div class="rname">High Contrast</div><div class="help">Increase contrast between interface surfaces and text.</div></div><div class="switch" data-key="high_contrast"></div></div><div class="row"><div class="copy"><div class="rname">Reduce Motion</div><div class="help">Disable most interface transitions and animations.</div></div><div class="switch" data-key="reduce_motion"></div></div><div class="row"><div class="copy"><div class="rname">Screen Reader Friendly Mode</div><div class="help">Increase focus visibility in this settings interface.</div></div><div class="switch" data-key="screen_reader_mode"></div></div></div></section>
</div></main></div>
<div class="modal" id="passwordModal"><div class="modalbox"><h3>Change Password</h3><p>Verify your current password before saving the new one.</p><form id="passwordForm"><div class="field"><label>Current Password</label><input id="currentPassword" type="password" autocomplete="current-password" required></div><div class="field" style="margin-top:13px"><label>New Password</label><input id="newPassword" type="password" minlength="8" autocomplete="new-password" required></div><div class="field" style="margin-top:13px"><label>Confirm New Password</label><input id="confirmPassword" type="password" minlength="8" autocomplete="new-password" required></div><div class="status" id="passwordStatus"></div><div class="modal-actions"><button class="btn secondary" type="button" id="closePassword">Cancel</button><button class="btn primary">Change Password</button></div></form></div></div>
<script>
const BASE=<?=json_encode(BASE_URL)?>,CSRF=document.querySelector('meta[name="csrf-token"]').content;let settings={};const titles={account:'My Account',profile:'Profiles',privacy:'Privacy & Safety',connections:'Connections',appearance:'Appearance',notifications:'Notifications',voice:'Voice & Audio',accessibility:'Accessibility'};
async function api(url,opts={}){const r=await fetch(url,{credentials:'same-origin',...opts,headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF,...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Request failed');return d}
function msg(id,text,ok=false){const e=document.getElementById(id);e.textContent=text;e.className='status '+(ok?'ok':'err');setTimeout(()=>{e.textContent='';e.className='status'},3500)}
function theme(t){let light=t==='light'||(t==='system'&&matchMedia('(prefers-color-scheme:light)').matches);document.documentElement.dataset.theme=light?'light':'dark';document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('active',b.dataset.theme===t));document.documentElement.classList.toggle('no-motion',!!settings.reduce_motion);document.documentElement.classList.toggle('high-contrast',!!settings.high_contrast)}
async function save(k,v){const d=await api(BASE+'/API/profile/settings.php',{method:'POST',body:JSON.stringify({[k]:v})});settings=d.settings||settings;render();}
function render(){document.querySelectorAll('.switch[data-key]').forEach(x=>x.classList.toggle('on',!!settings[x.dataset.key]));document.getElementById('gradient').value=settings.avatar_gradient||'#a855f7,#ec4899';document.getElementById('visibility').value=settings.profile_visibility||'everyone';document.getElementById('micVolume').value=settings.mic_volume??100;document.getElementById('outVolume').value=settings.output_volume??100;document.getElementById('micOut').value=(settings.mic_volume??100)+'%';document.getElementById('outOut').value=(settings.output_volume??100)+'%';theme(settings.theme||'dark')}
async function load(){try{const d=await api(BASE+'/API/profile/settings.php');settings=d.settings||{};render();await devices()}catch(e){console.error(e)}}
async function devices(){if(!navigator.mediaDevices?.enumerateDevices)return;try{const ds=await navigator.mediaDevices.enumerateDevices(),i=document.getElementById('inputDevice'),o=document.getElementById('outputDevice');i.innerHTML='<option value="">Default microphone</option>';o.innerHTML='<option value="">Default speaker</option>';ds.forEach(d=>{if(d.kind==='audioinput')i.add(new Option(d.label||'Microphone',d.deviceId));if(d.kind==='audiooutput')o.add(new Option(d.label||'Speaker',d.deviceId))});i.value=settings.input_device||'';o.value=settings.output_device||''}catch(e){}}
document.querySelectorAll('.navbtn[data-section]').forEach(b=>b.onclick=()=>{const s=b.dataset.section;document.querySelectorAll('.navbtn[data-section]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.section').forEach(x=>x.classList.toggle('active',x.id==='section-'+s));document.getElementById('title').textContent=titles[s]});
document.querySelectorAll('.switch[data-key]').forEach(x=>x.onclick=async()=>{const k=x.dataset.key,v=!settings[k];x.classList.toggle('on',v);try{await save(k,v);if(k==='notification_desktop'&&v&&'Notification'in window&&Notification.permission==='default')await Notification.requestPermission()}catch(e){x.classList.toggle('on',!v);alert(e.message)}});
document.querySelectorAll('[data-theme]').forEach(x=>x.onclick=async()=>{try{await save('theme',x.dataset.theme)}catch(e){alert(e.message)}});
document.getElementById('accountForm').onsubmit=async e=>{e.preventDefault();try{const d=await api(BASE+'/API/profile/update-profile.php',{method:'POST',body:JSON.stringify({full_name:document.getElementById('displayName').value.trim(),bio:document.getElementById('bio').value.trim(),avatar_color_gradient:settings.avatar_gradient||'#a855f7,#ec4899'})});document.getElementById('heroName').textContent=d.profile.full_name;document.getElementById('avatar').textContent=d.profile.full_name.charAt(0).toUpperCase();msg('accountStatus','Account saved.',true)}catch(e){msg('accountStatus',e.message)}};
document.getElementById('resetAccount').onclick=()=>{document.getElementById('displayName').value=<?=json_encode($name)?>;document.getElementById('bio').value=<?=json_encode($bio)?>};
document.getElementById('saveProfile').onclick=async()=>{try{const g=document.getElementById('gradient').value,v=document.getElementById('visibility').value;await api(BASE+'/API/profile/update-profile.php',{method:'POST',body:JSON.stringify({full_name:document.getElementById('displayName').value.trim(),bio:document.getElementById('bio').value.trim(),avatar_color_gradient:g})});await save('avatar_gradient',g);await save('profile_visibility',v);document.getElementById('avatar').style.background='linear-gradient(135deg,'+g+')';msg('profileStatus','Profile settings saved.',true)}catch(e){msg('profileStatus',e.message)}};
document.getElementById('micVolume').oninput=e=>document.getElementById('micOut').value=e.target.value+'%';document.getElementById('outVolume').oninput=e=>document.getElementById('outOut').value=e.target.value+'%';document.getElementById('micVolume').onchange=e=>save('mic_volume',+e.target.value).catch(a=>alert(a.message));document.getElementById('outVolume').onchange=e=>save('output_volume',+e.target.value).catch(a=>alert(a.message));document.getElementById('inputDevice').onchange=e=>save('input_device',e.target.value).catch(a=>alert(a.message));document.getElementById('outputDevice').onchange=e=>save('output_device',e.target.value).catch(a=>alert(a.message));
document.getElementById('testMic').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Microphone access is not supported by this browser.');const s=await navigator.mediaDevices.getUserMedia({audio:{noiseSuppression:!!settings.noise_suppression,echoCancellation:!!settings.echo_cancellation,autoGainControl:!!settings.auto_gain_control}});s.getTracks().forEach(t=>t.stop());await devices();msg('voiceStatus','Microphone access and audio capture work.',true)}catch(e){msg('voiceStatus',e.message)}};
document.getElementById('openPassword').onclick=()=>document.getElementById('passwordModal').classList.add('open');document.getElementById('closePassword').onclick=()=>document.getElementById('passwordModal').classList.remove('open');document.getElementById('passwordForm').onsubmit=async e=>{e.preventDefault();const a=document.getElementById('newPassword').value,b=document.getElementById('confirmPassword').value;if(a!==b){msg('passwordStatus','New passwords do not match.');return}try{await api(BASE+'/API/auth/change-password.php',{method:'POST',body:JSON.stringify({current_password:document.getElementById('currentPassword').value,new_password:a})});msg('passwordStatus','Password changed successfully.',true);e.target.reset();setTimeout(()=>document.getElementById('passwordModal').classList.remove('open'),900)}catch(x){msg('passwordStatus',x.message)}};
load();
</script></body></html>
